# Logo chính thức của provider (dùng nguyên bản, chỉ thu nhỏ bicubic chất lượng cao, không vẽ lại/đổi màu) — WPF, Windows PowerShell 5.1.
# Nguồn (tải 2026-11-21):
#   claude      — Claude Spark (Clay), bộ press kit chính thức của Anthropic: https://www.anthropic.com/press-kit
#                 (Anthropic logos/Claude logos/3 Claude Spark/PNG/Claude Spark - Clay.png, 937×937).
#   codex       — OpenAI Blossom (White; Codex chưa có logo riêng), bộ logo chính thức của OpenAI từ https://openai.com/brand/
#                 (https://cdn.openai.com/brand/openai-logos.zip → PNGs/OAI_OpenAI-Blossom_White.png, 716×716).
#   antigravity — Google-Antigravity-Icon-Full-Color.png (540×540), chủ dự án cung cấp.
# Mỗi logo nhúng dạng PNG base64 ở 96 px và 48 px (nền trong suốt). Dot-source chỉ định nghĩa hàm.
# Hợp đồng: Get-AgentViewLogo([string]$Family, [int]$Size) ⇒ ImageSource đã Freeze (cache theo Family + cỡ nguồn) hoặc $null (Family lạ).

function Get-AgentViewLogoData {
    @{
    'claude|96' = ''
    'claude|48' = ''
    'codex|96' = ''
    'codex|48' = ''
    'antigravity|96' = ''
    'antigravity|48' = ''
    }
}

# Cỡ ảnh nguồn cho một cỡ hiển thị (DIP): đủ nét tới 200% DPI ⇒ ≤24 DIP dùng 48 px, lớn hơn dùng 96 px.
function Get-AgentViewLogoSourceSize([int]$Size) {
    if ($Size -gt 0 -and $Size -le 24) { return 48 }
    return 96
}

function Get-AgentViewLogo([string]$Family, [int]$Size = 96) {
    if (-not $Family) { return $null }
    $px = Get-AgentViewLogoSourceSize $Size
    $key = $Family.ToLowerInvariant() + '|' + $px
    $cache = [AppDomain]::CurrentDomain.GetData('agent-view.logos')
    if ($null -eq $cache) { $cache = @{}; [AppDomain]::CurrentDomain.SetData('agent-view.logos', $cache) }
    if ($cache.ContainsKey($key)) { return $cache[$key] }
    $data = (Get-AgentViewLogoData)[$key]
    $image = $null
    if ($data) {
        try {
            if (Test-Path function:Initialize-AgentViewWpf) { Initialize-AgentViewWpf }
            elseif (-not ('System.Windows.Media.Imaging.BitmapImage' -as [type])) { Add-Type -AssemblyName PresentationFramework, PresentationCore, WindowsBase }
            $stream = New-Object System.IO.MemoryStream (, [Convert]::FromBase64String($data))
            try {
                $image = New-Object System.Windows.Media.Imaging.BitmapImage
                $image.BeginInit()
                $image.CacheOption = [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
                $image.StreamSource = $stream
                $image.EndInit()
                $image.Freeze()
            } finally { $stream.Dispose() }
        } catch { $image = $null }
    }
    $cache[$key] = $image
    $image
}
